package app.studyforge.mobile;

import org.junit.Test;
import org.json.*;
import java.util.*;
import java.io.*;
import javax.crypto.spec.SecretKeySpec;
import static org.junit.Assert.*;

public class WholeBookTest {
    static JSONArray book(int pages) throws Exception{return Json.array(Json.object("id","book","title","교재 전체","role","textbook","text","","images",new JSONArray(),"document",Json.object("kind","pdf","pages",pages,"sha256","original-hash")));}
    static final class Memory implements AnalysisPipeline.Store {final Map<String,JSONObject> rows=new HashMap<>();public JSONObject get(String key) throws Exception{return rows.containsKey(key)?Json.copy(rows.get(key)):new JSONObject();}public void put(String key,JSONObject value) throws Exception{rows.put(key,Json.copy(value));}}
    static class Fake implements AnalysisPipeline.Model,AnalysisPipeline.Loader {
        final Set<Integer> read=new HashSet<>();int extracts,combines,loads,failAt=-1;boolean unreadable=false,cancelAfterCall=false;Runnable after=()->{};
        public JSONArray load(JSONObject unit) throws Exception {loads++;JSONArray images=new JSONArray();for(int p=unit.getInt("loadStart");p<=unit.getInt("loadEnd");p++)images.put(Json.object("page",p,"data","data:image/jpeg;base64,AA=="));assertTrue(images.length()<=10);return Json.array(Json.object("id","book","title","교재 전체","role","textbook","text","","images",images));}
        public JSONObject call(String instructions,JSONArray input) throws Exception {
            if(instructions.equals(AnalysisPipeline.EXTRACT)){extracts++;if(extracts==failAt)throw new IOException("network interrupted");JSONArray pages=new JSONArray();for(int i=0;i<input.length();i++){String text=input.getJSONObject(i).optString("text");if(text.contains("실제 PDF page=")){int p=Integer.parseInt(text.substring(text.indexOf("실제 PDF page=")+12));read.add(p);pages.put(Json.object("source_id","book","page",p,"status",unreadable?"unreadable":"read","reason",unreadable?"blurred":"","notes",unreadable?new JSONArray():Json.array(Json.object("quote","원문 "+p,"text","이 페이지의 학습 개념 "+p,"topic","단원 "+p,"kind","concept"))));}}after.run();return Json.object("pages",pages);}
            combines++;String text=input.getJSONObject(0).getString("text");JSONArray rows=new JSONArray(text.substring(text.indexOf("\n[")+1)),ids=new JSONArray();int coverage=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.has("id")){coverage++;if(ids.length()<16)ids.put(row.getString("id"));}else{coverage+=Integer.parseInt(row.getString("overview").substring(9));JSONArray child=row.getJSONArray("selected_evidence");for(int j=0;j<child.length()&&ids.length()<16;j++)ids.put(child.getString(j));}}return Json.object("overview","coverage="+coverage,"selected_evidence",ids);
        }
    }
    static AnalysisPipeline pipe(Memory store,Fake fake,List<JSONObject> states){return new AnalysisPipeline(store,fake,fake,()->{},s->states.add(Json.copy(s)));}
    @Test public void plansEveryPageExactlyOnceWithBoundaryContext() throws Exception {JSONArray plan=BatchPlan.create(book(503));int[] count=new int[504];for(int i=0;i<plan.length();i++){JSONObject u=plan.getJSONObject(i);for(int p=u.getInt("start");p<=u.getInt("end");p++)count[p]++;assertTrue(u.getInt("loadStart")>=1);assertTrue(u.getInt("loadEnd")<=503);assertTrue(u.getInt("loadEnd")-u.getInt("loadStart")<6);}for(int p=1;p<=503;p++)assertEquals(1,count[p]);assertEquals(503,BatchPlan.totalPages(plan));}
    @Test public void fiveHundredPagesAreReadAndAllChunksReachTheGlobalSummary() throws Exception {Memory store=new Memory();Fake fake=new Fake();List<JSONObject> states=new ArrayList<>();AnalysisPipeline.Result result=pipe(store,fake,states).run(book(500),"account-model","시험 기준");assertEquals(63,fake.extracts);assertEquals(500,fake.read.size());assertTrue(fake.combines>1);JSONObject last=states.get(states.size()-1);assertEquals(500,last.getInt("pagesDone"));assertEquals(125,last.getInt("done"));assertEquals("ready",last.getString("phase"));assertEquals("coverage="+last.getInt("notes"),result.overview());assertEquals(500,result.sources().getJSONObject(0).getJSONObject("document").getInt("pages"));assertEquals(0,result.sources().getJSONObject(0).getJSONArray("images").length());}
    @Test public void networkFailureResumesWithoutRereadingCompletedChunks() throws Exception {Memory store=new Memory();Fake fake=new Fake();List<JSONObject> states=new ArrayList<>();fake.failAt=3;assertThrows(IOException.class,()->pipe(store,fake,states).run(book(30),"same-model","same criteria"));assertEquals(4,states.get(states.size()-1).getInt("done"));fake.failAt=-1;AnalysisPipeline.Result result=pipe(store,fake,states).run(book(30),"same-model","same criteria");assertEquals(5,fake.extracts);assertEquals(30,result.receipt().getInt("pagesDone"));int calls=fake.extracts,summaries=fake.combines;pipe(store,fake,states).run(book(30),"same-model","same criteria");assertEquals(calls,fake.extracts);assertEquals(summaries,fake.combines);}
    @Test public void cancellationDoesNotCommitAnInFlightChunk() throws Exception {Memory store=new Memory();Fake fake=new Fake();boolean[] canceled={false};fake.after=()->canceled[0]=true;AnalysisPipeline p=new AnalysisPipeline(store,fake,fake,()->{if(canceled[0])throw new java.util.concurrent.CancellationException();},s->{});assertThrows(java.util.concurrent.CancellationException.class,()->p.run(book(4),"m",""));assertTrue(store.rows.keySet().stream().noneMatch(k->k.startsWith("chunk_")));}
    @Test public void unreadableAndMissingPagesNeverCountAsCompleted() throws Exception {Memory store=new Memory();Fake fake=new Fake();fake.unreadable=true;List<JSONObject> states=new ArrayList<>();assertThrows(Exception.class,()->pipe(store,fake,states).run(book(20),"m",""));assertEquals(0,states.get(states.size()-1).getInt("done"));JSONObject unit=BatchPlan.create(book(4)).getJSONObject(0);assertThrows(Exception.class,()->AnalysisPipeline.validate(Json.object("pages",new JSONArray()),fake.load(unit),unit));}
    @Test public void modelAndFileChangesInvalidateOnlyTheirOwnCache() throws Exception {Memory store=new Memory();Fake fake=new Fake();List<JSONObject> states=new ArrayList<>();pipe(store,fake,states).run(book(8),"model-a","");assertEquals(1,fake.extracts);pipe(store,fake,states).run(book(8),"model-b","");assertEquals(2,fake.extracts);JSONArray updated=book(8);updated.getJSONObject(0).getJSONObject("document").put("sha256","changed");pipe(store,fake,states).run(updated,"model-b","");assertEquals(3,fake.extracts);}
    @Test public void longTextHasNoCharacterGapsAndUsesSmallRequests() throws Exception {String text="가".repeat(250001);JSONArray sources=Json.array(Json.object("id","text","title","긴 녹취","role","transcript","text",text,"images",new JSONArray()));JSONArray plan=BatchPlan.create(sources);int offset=0;for(int i=0;i<plan.length();i++){JSONObject unit=plan.getJSONObject(i);assertEquals(offset,unit.getInt("start"));offset=unit.getInt("end");assertTrue(unit.getInt("loadEnd")-unit.getInt("loadStart")<=18600);}assertEquals(text.length(),offset);}
    @Test public void selectedQuotesMustMatchAnalyzedOriginalPages() throws Exception {JSONArray sources=book(500);sources.getJSONObject(0).put("evidence",Json.array(Json.object("page",300,"quote","실제 원문 발췌")));Map<String,JSONObject> map=PastExpansion.sourceMap(sources);QuestionValidator.citation(Json.object("source_id","book","page",300,"quote","원문"),map);assertThrows(Exception.class,()->QuestionValidator.citation(Json.object("source_id","book","page",301,"quote","원문"),map));assertThrows(Exception.class,()->QuestionValidator.citation(Json.object("source_id","book","page",300,"quote","없는 내용"),map));}
    @Test public void encryptedOriginalStreamsMultipleBlocksAndDetectsTampering() throws Exception {byte[] bytes=new byte[EncryptedBlocks.BLOCK*3+111];new Random(27).nextBytes(bytes);var key=new SecretKeySpec(new byte[32],"AES");ByteArrayOutputStream encrypted=new ByteArrayOutputStream();var first=EncryptedBlocks.write(new ByteArrayInputStream(bytes),encrypted,key,"file-id",bytes.length);ByteArrayOutputStream plain=new ByteArrayOutputStream();var second=EncryptedBlocks.read(new ByteArrayInputStream(encrypted.toByteArray()),plain,key,"file-id");assertArrayEquals(bytes,plain.toByteArray());assertEquals(first,second);byte[] bad=encrypted.toByteArray();bad[30]^=1;assertThrows(Exception.class,()->EncryptedBlocks.read(new ByteArrayInputStream(bad),new ByteArrayOutputStream(),key,"file-id"));assertThrows(Exception.class,()->EncryptedBlocks.read(new ByteArrayInputStream(encrypted.toByteArray()),new ByteArrayOutputStream(),key,"wrong-file"));byte[] truncated=Arrays.copyOf(encrypted.toByteArray(),encrypted.size()-1);assertThrows(Exception.class,()->EncryptedBlocks.read(new ByteArrayInputStream(truncated),new ByteArrayOutputStream(),key,"file-id"));assertThrows(IOException.class,()->EncryptedBlocks.write(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),key,"file-id",100));}
    @Test public void pagedAnalysisReportIncludesLaterBookSections() throws Exception {Memory store=new Memory();Fake fake=new Fake();AnalysisPipeline.Result result=pipe(store,fake,new ArrayList<>()).run(book(100),"m","");JSONObject first=AnalysisPipeline.report(store,result.receipt().getString("key"),0);assertEquals(30,first.getJSONArray("rows").length());assertTrue(first.getBoolean("more"));JSONObject next=AnalysisPipeline.report(store,result.receipt().getString("key"),60);assertTrue(next.getJSONArray("rows").getJSONObject(0).getInt("page")>30);}
    @Test public void cancelStopsLargeFileCopyAtTheNextEncryptedBlock() throws Exception {byte[] bytes=new byte[EncryptedBlocks.BLOCK*3];int[] calls={0};ByteArrayOutputStream out=new ByteArrayOutputStream();assertThrows(java.util.concurrent.CancellationException.class,()->EncryptedBlocks.write(new ByteArrayInputStream(bytes),out,new SecretKeySpec(new byte[32],"AES"),"file",bytes.length,()->{if(++calls[0]>1)throw new java.util.concurrent.CancellationException();}));assertTrue(out.size()<bytes.length);}
    @Test public void reusesPreviousFourPageCheckpointAfterBatchingUpdate() throws Exception {
        JSONArray sources=book(12),plan=BatchPlan.create(sources);Memory store=new Memory();Fake fake=new Fake();JSONObject unit=plan.getJSONObject(0);JSONArray material=fake.load(unit);JSONObject response=fake.call(AnalysisPipeline.EXTRACT,StudyGenerator.materials(material));
        JSONObject cached=AnalysisPipeline.validate(response,material,unit).put("unit_id",unit.getString("id"));String key=AnalysisPipeline.chunkKey("m",unit);store.put(key,cached);int calls=fake.extracts;fake.read.clear();
        AnalysisPipeline.Result result=pipe(store,fake,new ArrayList<>()).run(sources,"m","");assertEquals(calls+1,fake.extracts);assertFalse(fake.read.contains(1));assertFalse(fake.read.contains(2));assertFalse(fake.read.contains(3));assertEquals(cached.toString(),store.get(key).toString());assertEquals(12,result.receipt().getInt("pagesDone"));
    }
    static final class ConcurrentFake extends Fake {
        final java.util.concurrent.atomic.AtomicInteger active=new java.util.concurrent.atomic.AtomicInteger(),peak=new java.util.concurrent.atomic.AtomicInteger(),attempts=new java.util.concurrent.atomic.AtomicInteger();
        final java.util.concurrent.CountDownLatch started=new java.util.concurrent.CountDownLatch(3);boolean rateOnce=false,failFirst=false;final java.util.concurrent.atomic.AtomicBoolean first=new java.util.concurrent.atomic.AtomicBoolean(true),canceled=new java.util.concurrent.atomic.AtomicBoolean(false);boolean cancelDuring=false;
        @Override public JSONObject call(String instructions,JSONArray input)throws Exception{
            if(!instructions.equals(AnalysisPipeline.EXTRACT))return super.call(instructions,input);
            int now=active.incrementAndGet();peak.accumulateAndGet(now,Math::max);attempts.incrementAndGet();started.countDown();
            try{started.await(3,java.util.concurrent.TimeUnit.SECONDS);Thread.sleep(8);
                boolean isFirst=input.toString().contains("PDF page=1\"");
                if(isFirst&&first.getAndSet(false)){if(rateOnce)throw new AnalysisPipeline.RateLimited("slow down");if(failFirst)throw new IOException("failed first batch");}
                if(cancelDuring)canceled.set(true);
                synchronized(this){return super.call(instructions,input);}
            }finally{active.decrementAndGet();}
        }
    }
    @Test public void concurrentReadingHasIdenticalEvidenceAndCoversAllFiveHundredPages()throws Exception{
        Fake serial=new Fake();AnalysisPipeline.Result expected=pipe(new Memory(),serial,new ArrayList<>()).run(book(500),"m","criteria");
        ConcurrentFake concurrent=new ConcurrentFake();List<JSONObject> states=new ArrayList<>();AnalysisPipeline.Result actual=new AnalysisPipeline(new Memory(),concurrent,concurrent,()->{},v->states.add(Json.copy(v)),3).run(book(500),"m","criteria");
        assertEquals(3,concurrent.peak.get());assertEquals(0,concurrent.active.get());assertEquals(63,concurrent.extracts);assertEquals(500,concurrent.read.size());assertEquals(expected.sources().toString(),actual.sources().toString());assertEquals(expected.overview(),actual.overview());assertEquals(500,actual.receipt().getInt("pagesDone"));
    }
    @Test public void rateLimitLowersConcurrencyAndRetriesOnlyTheRejectedBatch()throws Exception{
        ConcurrentFake fake=new ConcurrentFake();fake.rateOnce=true;List<JSONObject> states=new ArrayList<>();AnalysisPipeline.Result result=new AnalysisPipeline(new Memory(),fake,fake,()->{},v->states.add(Json.copy(v)),3).run(book(40),"m","");
        assertEquals(40,result.receipt().getInt("pagesDone"));assertEquals(6,fake.attempts.get());assertEquals(5,fake.extracts);assertTrue(states.stream().anyMatch(v->v.optInt("parallelism")==1));
    }
    @Test public void aFailedBatchDoesNotDiscardOtherCompletedParallelBatches()throws Exception{
        ConcurrentFake fake=new ConcurrentFake();fake.failFirst=true;Memory store=new Memory();List<JSONObject> states=new ArrayList<>();AnalysisPipeline pipeline=new AnalysisPipeline(store,fake,fake,()->{},v->states.add(Json.copy(v)),3);
        assertThrows(IOException.class,()->pipeline.run(book(24),"m",""));long saved=store.rows.keySet().stream().filter(k->k.startsWith("chunk_")).count();assertEquals(4,saved);assertEquals(4,states.get(states.size()-1).getInt("done"));assertEquals(16,states.get(states.size()-1).getInt("pagesDone"));int requests=fake.attempts.get();fake.failFirst=false;
        AnalysisPipeline.Result result=pipeline.run(book(24),"m","");assertEquals(requests+1,fake.attempts.get());assertEquals(24,result.receipt().getInt("pagesDone"));
    }
    @Test public void cancelingParallelReadsNeverCommitsInFlightResults()throws Exception{
        ConcurrentFake fake=new ConcurrentFake();fake.cancelDuring=true;Memory store=new Memory();AnalysisPipeline pipeline=new AnalysisPipeline(store,fake,fake,()->{if(fake.canceled.get())throw new java.util.concurrent.CancellationException();},v->{},3);
        assertThrows(java.util.concurrent.CancellationException.class,()->pipeline.run(book(24),"m",""));assertEquals(0,fake.active.get());assertTrue(store.rows.keySet().stream().noneMatch(k->k.startsWith("chunk_")));
    }
    @Test public void fileProgressReportsActualBytesWithoutChangingStoredContent()throws Exception{
        byte[] original=new byte[EncryptedBlocks.BLOCK*2+73];new Random(4).nextBytes(original);List<Long> written=new ArrayList<>(),read=new ArrayList<>();ByteArrayOutputStream encrypted=new ByteArrayOutputStream(),plain=new ByteArrayOutputStream();var key=new SecretKeySpec(new byte[32],"AES");
        EncryptedBlocks.write(new ByteArrayInputStream(original),encrypted,key,"progress-file",original.length,()->{},written::add);EncryptedBlocks.read(new ByteArrayInputStream(encrypted.toByteArray()),plain,key,"progress-file",()->{},read::add);
        assertEquals(Arrays.asList((long)EncryptedBlocks.BLOCK,2L*EncryptedBlocks.BLOCK,(long)original.length),written);assertEquals(written,read);assertArrayEquals(original,plain.toByteArray());
    }
    @Test public void latePdfBatchUsesOnlyActualPagesAndNeverAdvertisesAnExtraTextPage()throws Exception{
        JSONArray source=book(12);JSONObject unit=BatchPlan.create(source).getJSONObject(2);Fake fake=new Fake();JSONArray material=fake.load(unit),input=AnalysisPipeline.extractionInput(material);
        assertFalse(input.getJSONObject(0).getString("text").contains("텍스트 page=1"));String contract=input.getJSONObject(input.length()-1).getString("text");JSONArray manifest=new JSONArray(contract.substring(contract.indexOf('\n')+1));JSONArray actual=manifest.getJSONObject(0).getJSONArray("pages");assertEquals(8,actual.getInt(0));assertEquals(12,actual.getInt(actual.length()-1));
        JSONObject response=fake.call(AnalysisPipeline.EXTRACT,input);AnalysisPipeline.validate(response,material,unit);response.getJSONArray("pages").put(Json.object("source_id","book","page",1,"status","blank","reason","empty header","notes",new JSONArray()));Exception error=assertThrows(Exception.class,()->AnalysisPipeline.validate(response,material,unit));assertTrue(error.getMessage().contains("요청하지 않은 1쪽"));
    }
}
